/* * Structure for osk_version() */struct oskversion {  int  level;           /* OSK level */  int  version;         /* OSK version */  int  revision;        /* revision */  int  edition;         /* edition */  int  cpu;             /* CPU type (from init module) */  int  cpu_run;         /* CPU type (real CPU, from system globals) */  char mainframe[64];   /* mainframe */  char os9rev[64];      /* os9 revision string */};